    "setup": "// file: app/layout.tsx\nexport default function RootLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <html lang=\"ar\" dir=\"rtl\">\n      <body>{children}</body>\n    </html>\n  );\n}",
    "starter": "// file: app/blog/page.tsx\nexport default function Blog() {\n  return <h1>المدونة</h1>;\n}",
